const body = $input.first().json.body;
const TEMPLATES = {
  cover:    '1th6qlcsAwd0Sd3sOUo7lQ28PsaHMv20CbR6sivr_sjE',
  tds:      '1pQ4elE7evs4TmKnXYlCiVUPLdO0-SXJ1y4YAFErEPXU',
  warranty: '1equRpuRmmfq1Xs28kE6m7SVOcCIK4VpufzwRpaaxHgw',
  origin:   '14XKE586Vl8GX6hFZVUF2AIH8_6fhzceV_xs3Q8uMY6U'
};
const SHEET_TEMPLATES = {
  maf:  '1lgUIHGJx9pgap4ODM4gq2x7k7EJTDwu4uqE2T6HZOMQ',
  msdf: '1XTXQ8y2WUUfeQirBasZ85kmvWpN6yBuuIzRsfCuzwSc'
};
const ALL = Object.assign({}, TEMPLATES, SHEET_TEMPLATES);
const aiDocs = (body.selectedDocs || []).filter(k => ALL[k]);
if (aiDocs.length === 0) return [{ json: { _empty: true, projectInfo: body.projectInfo } }];
const date = new Date(body.projectInfo.date || Date.now());
const dd = String(date.getDate()).padStart(2,'0');
const mm = String(date.getMonth()+1).padStart(2,'0');
return aiDocs.map(docKey => ({
  json: {
    docKey,
    templateId: ALL[docKey],
    kind: SHEET_TEMPLATES[docKey] ? 'sheet' : 'doc',
    projectInfo: body.projectInfo,
    refNumber: docKey === 'origin' ? 'MS-COO-' + dd + '-' + mm + '-01' : 'MS-DW-' + dd + '-' + mm + '-01'
  }
}));

const doc = $input.item.json;
const copy = $('Copy Template').itemMatching($itemIndex).json;
const orig = $('Build Template Map').itemMatching($itemIndex).json;
const p = orig.projectInfo || {};

const formatDate = (s) => {
  if (!s) return '';
  const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[3] + '-' + m[2] + '-' + m[1];
  return s;
};
const safe = (v) => (v === null || v === undefined) ? '' : String(v);
const withMs = (val) => {
  const s = safe(val).trim();
  return s ? 'M/s. ' + s : '';
};

const PRODUCT_EXCLUSIONS = [
  { match: ['litter bin','litterbin','waste bin','wastebin','trash bin','trashbin',
            'litter container','recycle bin','recyclebin','recycling bin'],
    text: ' excluding liners' }
];
const detectExclusion = (productName, productList) => {
  const hay = (safe(productName) + ' ' + safe(productList)).toLowerCase();
  for (const rule of PRODUCT_EXCLUSIONS) {
    if (rule.match.some(kw => hay.includes(kw))) return rule.text;
  }
  return '';
};
const exclusionClause = detectExclusion(p.productName, p.productList);

const replacements = {
  'M/s. {{CLIENT}}':           withMs(p.client),
  'M/s.  {{CLIENT}}':          withMs(p.client),
  'M/s. {{MAIN_CONTRACTOR}}':  withMs(p.mainContractor),
  'M/s.  {{MAIN_CONTRACTOR}}': withMs(p.mainContractor),
  'M/s. {{SUB_CONTRACTOR}}':   withMs(p.subContractor),
  'M/s.  {{SUB_CONTRACTOR}}':  withMs(p.subContractor),
  '{{PROJECT_NAME}}':    safe(p.projectName),
  '{{CLIENT}}':          safe(p.client),
  '{{MAIN_CONTRACTOR}}': safe(p.mainContractor),
  '{{SUB_CONTRACTOR}}':  safe(p.subContractor),
  '{{PRODUCT_NAME}}':    safe(p.productName),
  '{{MATERIAL_SPEC}}':   safe(p.materialSpec),
  '{{DIMENSIONS}}':      safe(p.dimensions),
  '{{MATERIAL}}':        safe(p.material),
  '{{FINISH}}':          safe(p.finish),
  '{{PRODUCT_WARRANTY}}':safe(p.productWarranty).toLowerCase(),
  '{{PRODUCT_LIST}}':    safe(p.productList),
  '{{REF_NUMBER}}':      safe(orig.refNumber),
  '{{DATE}}':            formatDate(p.date),
  '{{QUOTE}}':           safe(p.quoteNumber),
  '{{QUOTE_NUMBER}}':    safe(p.quoteNumber),
  '{{QUOTATION}}':       safe(p.quoteNumber),
  '{{QUOTATION_NUMBER}}':safe(p.quoteNumber),
  '{{EXCLUSION_CLAUSE}}':exclusionClause
};
const requests = Object.entries(replacements).map(([k,v]) => ({
  replaceAllText: { containsText: { text: k, matchCase: true }, replaceText: String(v) }
}));

let imgDebug = { tdsAndUrl: orig.docKey==='tds' && !!p.productImageUrl,
  bodyInline:0, bodyPositioned:0, chosen:null, chosenType:null };

if (orig.docKey === 'tds' && p.productImageUrl) {
  const bodyInlineIds = [];
  const bodyPositionedIds = [];
  const walk = (content) => {
    if (!Array.isArray(content)) return;
    for (const el of content) {
      if (el.paragraph && Array.isArray(el.paragraph.elements)) {
        for (const pe of el.paragraph.elements) {
          if (pe.inlineObjectElement && pe.inlineObjectElement.inlineObjectId)
            bodyInlineIds.push(pe.inlineObjectElement.inlineObjectId);
          if (pe.positionedObjectReferenceElement && pe.positionedObjectReferenceElement.positionedObjectId)
            bodyPositionedIds.push(pe.positionedObjectReferenceElement.positionedObjectId);
        }
      }
      if (el.table && el.table.tableRows) {
        for (const row of el.table.tableRows)
          for (const cell of (row.tableCells||[])) walk(cell.content);
      }
    }
  };
  walk(doc.body && doc.body.content);
  imgDebug.bodyInline = bodyInlineIds.length;
  imgDebug.bodyPositioned = bodyPositionedIds.length;

  let target = null;
  if (bodyPositionedIds.length) target = { type:'positioned', id: bodyPositionedIds[bodyPositionedIds.length-1] };
  else if (bodyInlineIds.length) target = { type:'inline', id: bodyInlineIds[bodyInlineIds.length-1] };
  else if (doc.positionedObjects && Object.keys(doc.positionedObjects).length) {
    const ks = Object.keys(doc.positionedObjects);
    target = { type:'positioned-fallback', id: ks[ks.length-1] };
  }

  if (target) {
    let size = null;
    if (target.type === 'inline' && doc.inlineObjects && doc.inlineObjects[target.id]) {
      size = doc.inlineObjects[target.id].inlineObjectProperties &&
             doc.inlineObjects[target.id].inlineObjectProperties.embeddedObject &&
             doc.inlineObjects[target.id].inlineObjectProperties.embeddedObject.size;
    } else if (doc.positionedObjects && doc.positionedObjects[target.id]) {
      size = doc.positionedObjects[target.id].positionedObjectProperties &&
             doc.positionedObjects[target.id].positionedObjectProperties.embeddedObject &&
             doc.positionedObjects[target.id].positionedObjectProperties.embeddedObject.size;
    }
    const w = Math.round((size && size.width && size.width.magnitude) || 200);
    const h = Math.round((size && size.height && size.height.magnitude) || 300);
    const wrappedUrl = 'https://wsrv.nl/?url=' + encodeURIComponent(p.productImageUrl)
      + '&w=' + (w*3) + '&h=' + (h*3) + '&fit=contain&cbg=white&output=jpg&q=90';
    imgDebug.chosen = target.id;
    imgDebug.chosenType = target.type;
    requests.push({
      replaceImage: { imageObjectId: target.id, uri: wrappedUrl, imageReplaceMethod: 'CENTER_CROP' }
    });
  }
}

return { json: { docId: copy.id, docKey: orig.docKey, requests, _imgDebug: imgDebug } };

const br = $('Build Replacements').itemMatching($itemIndex).json;
return {
  json: {
    docKey: br.docKey,
    viewLink: 'https://docs.google.com/document/d/' + br.docId + '/edit',
    downloadLink: 'https://docs.google.com/document/d/' + br.docId + '/export?format=docx',
    _imgDebug: br._imgDebug
  }
};

const docs = {};
const debug = {};
for (const item of $input.all()) {
  if (item.json && item.json.docKey) {
    docs[item.json.docKey] = { viewLink: item.json.viewLink, downloadLink: item.json.downloadLink };
    if (item.json._imgDebug) debug[item.json.docKey] = item.json._imgDebug;
  }
}
return [{ json: { success: true, documents: docs, _imgDebug: debug } }];

const copy = $('Copy Template').itemMatching($itemIndex).json;
const orig = $('Build Template Map').itemMatching($itemIndex).json;
const p = orig.projectInfo || {};
const safe = (v) => (v === null || v === undefined) ? '' : String(v);
const formatDate = (s) => {
  const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[3] + '-' + m[2] + '-' + m[1] : safe(s);
};
const reps = {
  '{{PROJECT_NAME}}':     safe(p.projectName),
  '{{CLIENT}}':           safe(p.client),
  '{{MAIN_CONTRACTOR}}':  safe(p.mainContractor),
  '{{SUB_CONTRACTOR}}':   safe(p.subContractor),
  '{{CONSULTANT}}':       safe(p.consultant),
  '{{LOCATION}}':         safe(p.location),
  '{{PRODUCT_NAME}}':     safe(p.productName),
  '{{MATERIAL_SPEC}}':    safe(p.materialSpec),
  '{{DIMENSIONS}}':       safe(p.dimensions),
  '{{MATERIAL}}':         safe(p.material),
  '{{FINISH}}':           safe(p.finish),
  '{{DATE}}':             formatDate(p.date),
  '{{QUOTE}}':            safe(p.quoteNumber),
  '{{QUOTE_NUMBER}}':     safe(p.quoteNumber),
  '{{QUOTATION}}':        safe(p.quoteNumber),
  '{{QUOTATION_NUMBER}}': safe(p.quoteNumber),
  '{{REF_NUMBER}}':       safe(orig.refNumber)
};
const requests = Object.entries(reps).map(([find, replacement]) => ({
  findReplace: { find: find, replacement: String(replacement), matchCase: true, allSheets: true }
}));
return { json: { sheetId: copy.id, docKey: orig.docKey, requests: requests } };

const sr = $('Build Sheet Replacements').itemMatching($itemIndex).json;
return { json: {
  docKey: sr.docKey,
  viewLink: 'https://docs.google.com/spreadsheets/d/' + sr.sheetId + '/edit',
  downloadLink: 'https://docs.google.com/spreadsheets/d/' + sr.sheetId + '/export?format=xlsx'
}};
